            aOrbiterJ = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 21U)) + 0xBE74F91FB5A79F84ULL) + aOrbiterAssignSaltA[((aIndex + 12U)) & S_SALT1];
