            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x420A66C1D95D3E6EULL) + aOrbiterUpdateSaltB[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x7930F419D49C70FEULL;
            aOrbiterB = RotL64((aOrbiterB * 0x518674BC2C163D73ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x40506B70222EEC09ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x849C495F93CE2E5EULL;
            aOrbiterC = RotL64((aOrbiterC * 0xB7F15677CE922F25ULL), 13U);
            //
            aOrbiterD = (((aOrbiterD + aOrbiterE) + 0xBB0CA591F8C40DEBULL) + aOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1]) + aNonceWordL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xBE98B46365C3C48AULL;
