            aOrbiterF = RotL64((aOrbiterF * 0x0AE9FCAA8D13A90FULL), 57U);
            //
            aIngress = RotL64(aOrbiterC, 47U) ^ aOrbiterJ;
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterE, 51U));
            aIngress = aIngress + (RotL64(aOrbiterF, 34U) ^ aOrbiterI);
