            //
            aScatter = (RotL64(aPrevious, 37U) + RotL64(aCross, 19U)) ^ (RotL64(aCarry, 6U) ^ RotL64(aIngress, 57U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterH = (aWandererJ + RotL64(aPrevious, 53U)) + 0x9AF63B353E919A9FULL;
            aOrbiterJ = ((aWandererK + RotL64(aCross, 47U)) + 0x13299577C67A8329ULL) + aTwistOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterA = (aWandererC + RotL64(aScatter, 3U)) + 0x08CEE5BF81B4D743ULL;
            aOrbiterF = (aWandererB + RotL64(aIngress, 27U)) + 0x5DE6C6635F0328C1ULL;
            aOrbiterD = ((aWandererI + RotL64(aScatter, 10U)) + RotL64(aCarry, 35U)) + 0x49FCA0F5834208C6ULL;
            aOrbiterC = ((aWandererE + RotL64(aPrevious, 41U)) + RotL64(aCarry, 13U)) + 0xCB5AA3A7F73AF0E5ULL;
            aOrbiterB = (((aWandererH + RotL64(aIngress, 21U)) + RotL64(aCarry, 47U)) + 0x5547D338115828C4ULL) + aTwistOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x01A92437B51E6ED1ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0xEA7AF6DA3B0427CBULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 16U)) & S_SALT1];
