            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x1E8B21828D2B7EFBULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x653DCED88F3D6522ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xDB51042EF9A0551BULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x46D528FA51AA7587ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0xEBB24B05DCDAAF95ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x55F98ABA6EC0943FULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xB3827090AE64AE9EULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x919398436AB6F9C9ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x835F67C7A1BEDDB1ULL), 51U);
            //
            aIngress = RotL64(aOrbiterH, 5U) ^ aOrbiterB;
            aIngress = aIngress + (RotL64(aOrbiterD, 51U) ^ aOrbiterJ);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterA, 57U));
            aIngress = aIngress + RotL64(aOrbiterF, 36U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aCross, 5U) + aOrbiterH) + RotL64(aOrbiterF, 39U)) + RotL64(aCarry, 41U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 11U) + aOrbiterH) + RotL64(aOrbiterJ, 51U));
            aWandererI = aWandererI + ((RotL64(aPrevious, 48U) + aOrbiterD) + RotL64(aOrbiterA, 3U));
            aWandererK = aWandererK ^ (((RotL64(aScatter, 29U) + aOrbiterB) + RotL64(aOrbiterF, 21U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 6U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aPrevious, 21U) + RotL64(aOrbiterD, 14U)) + aOrbiterC);
            aWandererC = aWandererC ^ (((RotL64(aIngress, 57U) + aOrbiterD) + RotL64(aOrbiterB, 57U)) + aTwistWandererUpdateSaltF[((aIndex + 11U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 35U) + RotL64(aOrbiterD, 27U)) + aOrbiterF) + RotL64(aCarry, 5U));
            //
            aCarry = aCarry + (RotL64(aWandererJ, 51U) ^ aWandererE);
