            //
            aIngress = (RotL64(aFireLaneC[((aIndex + 7648U)) & S_BLOCK1], 4U) ^ RotL64(aEarthLaneC[((aIndex + 7271U)) & S_BLOCK1], 13U));
            aIngress ^= RotL64(pSnowLaneA[((aIndex + 7031U)) & S_BLOCK1], 57U);
