            aCross = (RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 6636U)) & S_BLOCK1], 4U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 6053U)) & S_BLOCK1], 23U));
