            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCross, 44U) + RotL64(aIngress, 27U)) ^ (RotL64(aPrevious, 57U) + RotL64(aCarry, 13U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = ((aWandererF + RotL64(aScatter, 19U)) + RotL64(aCarry, 11U)) + 0x8C43DFBC74C93E74ULL;
            aOrbiterE = (((aWandererK + RotL64(aCross, 5U)) + RotL64(aCarry, 39U)) + 0xC769E680BF611929ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterA = (aWandererJ + RotL64(aIngress, 43U)) + 0xF9A465D32681060CULL;
            aOrbiterG = (((aWandererB + RotL64(aPrevious, 27U)) + RotL64(aCarry, 57U)) + 0x498D55B8A84D8D36ULL) + aTwistOrbiterAssignSaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterK = (aWandererA + RotL64(aScatter, 34U)) + 0x5A7B2689EDAFA98AULL;
            aOrbiterF = (aWandererC + RotL64(aIngress, 51U)) + 0x8653713573AF3121ULL;
            aOrbiterJ = (aWandererE + RotL64(aCross, 57U)) + 0xE3A40C409A6C7321ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x248E068C418EDBACULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0xC5B41667BA1B7C64ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xE16D16CAD7E7D487ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xD4DD450E9E83B5BCULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x5972B104421AF61BULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC9E8DD8E858B798FULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x2E7056C637D0338FULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x5E4B342C85C12A86ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x08ED08A74159F62DULL), 41U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x1F1518C8C6A5DC71ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x2F1A5873AB8F537DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x8D32A973A21D6C2FULL), 19U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0x8082B184D0271776ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 14U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x6C20A681D05BF3F6ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9BE5B0C548F40C6BULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x968107B4F82206A8ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xE6077985C8B9751AULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xDA0E2DF1E6C96CCDULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xD739F2D22223410EULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterK) ^ 0x7A94FC81626F8E86ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x36316A7D4AA6C1D3ULL), 29U);
            //
            aIngress = RotL64(aOrbiterE, 5U) ^ aOrbiterG;
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterH, 11U));
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterK, 23U));
            aIngress = aIngress + RotL64(aOrbiterA, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ ((RotL64(aIngress, 43U) + aOrbiterJ) + RotL64(aOrbiterK, 41U));
            aWandererC = aWandererC + (((RotL64(aCross, 51U) + aOrbiterF) + RotL64(aOrbiterK, 27U)) + RotL64(aCarry, 27U));
            aWandererF = aWandererF ^ (((RotL64(aScatter, 3U) + aOrbiterE) + RotL64(aOrbiterG, 6U)) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aPrevious, 57U) + RotL64(aOrbiterA, 21U)) + aOrbiterG) + RotL64(aCarry, 3U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 14U) + RotL64(aOrbiterH, 57U)) + aOrbiterE);
