            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x9A20DE718E0A915EULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 27U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x2266F29EBD84BF83ULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x3250A54B55853EA3ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x70735813F591B106ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x1A05B0AB7E5A985FULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x5C714380B2A7ADB8ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0xE13946C95A689EE9ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
