            aWandererJ = aWandererJ + ((((RotL64(aIngress, 57U) + aOrbiterE) + RotL64(aOrbiterI, 37U)) + RotL64(aCarry, 53U)) + aTwistWandererUpdateSaltD[((aIndex + 5U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aCross, 41U) + aOrbiterE) + RotL64(aOrbiterK, 5U));
            aWandererE = aWandererE + (((RotL64(aPrevious, 11U) + aOrbiterK) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 19U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 21U) + aOrbiterD) + RotL64(aOrbiterC, 13U));
