            //
            aOrbiterB = ((aWandererH + RotL64(aIngress, 13U)) + 0xA4D4EB957F2A3DE6ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterK = ((aWandererI + RotL64(aCross, 51U)) + RotL64(aCarry, 23U)) + 0x12A650F0E436925EULL;
