            aOrbiterH = ((aWandererB + RotL64(aScatter, 29U)) + RotL64(aCarry, 3U)) + 0x198348B8AAC847DDULL;
            aOrbiterI = (aWandererG + RotL64(aPrevious, 21U)) + 0xB8113063E268E4A9ULL;
            aOrbiterE = ((aWandererC + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0xE5CBBA044142A2A0ULL;
            aOrbiterF = (aWandererE + RotL64(aScatter, 37U)) + 0x4392CAB9CC3EFB1BULL;
