            aIngress ^= (RotL64(aEarthLaneC[((aIndex + 12087U)) & S_BLOCK1], 56U) ^ RotL64(aFireLaneB[((aIndex + 9639U)) & S_BLOCK1], 3U));
            aIngress = TwistMix64::DiffuseC(aIngress);
