            aCross = (RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 12476U)) & S_BLOCK1], 13U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 9728U)) & S_BLOCK1], 5U));
            aCross ^= (RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 15421U)) & S_BLOCK1], 44U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 9571U)) & S_BLOCK1], 53U));
