            aScatter = (RotL64(aIngress, 24U) ^ RotL64(aCross, 39U)) ^ (RotL64(aPrevious, 51U) + RotL64(aCarry, 3U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererD + RotL64(aIngress, 47U)) + 0x5ED7AC6AA6289122ULL;
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 4U)) + RotL64(aCarry, 23U)) + 0x57EED9D8C1739D29ULL;
            aOrbiterA = ((aWandererE + RotL64(aCross, 11U)) + 0xEE530D512C04B9DBULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterJ = ((aWandererC + RotL64(aScatter, 27U)) + RotL64(aCarry, 11U)) + 0x68CEEA2EDDDC24C9ULL;
            aOrbiterC = ((aWandererK + RotL64(aCross, 53U)) + 0x96A75658835EFA69ULL) + aTwistOrbiterAssignSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aIngress, 37U)) + RotL64(aCarry, 39U)) + 0x5533EC3D0B7B4328ULL;
            aOrbiterB = (aWandererB + RotL64(aScatter, 21U)) + 0x19BAFDB237AA0424ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x59328B20EE7A0CFCULL) + aTwistOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xAD58A42BEAB1A0CAULL;
            aOrbiterA = RotL64((aOrbiterA * 0x97F09AB8EA1877C1ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x725E70C58D276A4CULL;
