            aOrbiterC = RotL64((aOrbiterC * 0x16F8B3459D6E1C8DULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xB792332E0A258986ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0x47914AA7C07F4988ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x4725E1B1CD13E56FULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x4A0FAC2BA74D20D3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x51E5FD50888E71B8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xE734C1695F2E54BDULL), 29U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x57A61870C25C47ADULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x3F602717205E3F01ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA0C5C2CC671A5829ULL), 3U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x18DDA719770F1732ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x8D82A9DB60BA1E30ULL;
