            aOrbiterC = (aWandererB + RotL64(aPrevious, 19U)) + 0xE48FDFD4BE0865C9ULL;
            aOrbiterG = ((aWandererK + RotL64(aScatter, 3U)) + 0x599BB12A5EB91D6FULL) + aTwistOrbiterAssignSaltD[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = ((aWandererF + RotL64(aIngress, 53U)) + 0x05E3C2EA85519996ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 19U)) & S_SALT1];
            //
