            aOrbiterB = RotL64((aOrbiterB * 0x819EAA218411E065ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xE16CF0A735D713CDULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x6350766E83F524DCULL;
