            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x504229551B472C7CULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0xE8D1EF21F0CB71B9ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x725595443A2E54F3ULL), 39U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x71DAB1781E30DEEAULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x91E0721ABE3A0504ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x3068821FC4840519ULL), 29U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x271C30F1D59CDD81ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 18U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xA68976FD9C147508ULL;
