            aWandererH = aWandererH ^ (((RotL64(aIngress, 5U) + RotL64(aOrbiterD, 35U)) + aOrbiterC) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1]);
