            aOrbiterE = (((aWandererK + RotL64(aCross, 21U)) + RotL64(aCarry, 3U)) + 0x9ADD1699961FAB0BULL) + aTwistOrbiterAssignSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aScatter, 37U)) + 0x809973F291247D3FULL;
            aOrbiterF = ((aWandererA + RotL64(aPrevious, 30U)) + RotL64(aCarry, 19U)) + 0x6E876A7191671286ULL;
            aOrbiterC = (aWandererD + RotL64(aScatter, 53U)) + 0x78A32C9719D277E1ULL;
            aOrbiterG = (aWandererH + RotL64(aCross, 13U)) + 0x513E3157A57A213FULL;
