            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x6F5188C6BE6EB202ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x9D8560A59DE54A75ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x1DC5E3C5949D1AC3ULL), 43U);
