            aCross = (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 2171U)) & S_BLOCK1], 13U) ^ RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 4632U)) & S_BLOCK1], 35U));
