            aOrbiterJ = ((aWandererI + RotL64(aCross, 40U)) + RotL64(aCarry, 39U)) + 0x3225137CC8F55E17ULL;
            aOrbiterK = ((aWandererC + RotL64(aIngress, 19U)) + RotL64(aCarry, 53U)) + 0x513BA772C39875E1ULL;
            aOrbiterI = ((aWandererE + RotL64(aPrevious, 13U)) + 0xA15334E7A0936BD3ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterF = ((aWandererK + RotL64(aScatter, 29U)) + RotL64(aCarry, 13U)) + 0xE6DEBE72DF9E6258ULL;
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 51U)) + 0x7DB3449E6E163992ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterB = (aWandererF + RotL64(aIngress, 5U)) + 0x7C84AE7842C55259ULL;
