            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0x6B0921B6D73F01CAULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x96B48F8EF32E213DULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x719C8F798AB3316FULL), 37U);
