            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xBD835DE51CA91CCBULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0x7889B8FAFAEE3558ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x58D7CC81A028E2E1ULL), 13U);
