            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0xEF5032CF2C056A0AULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 18U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0xC489A3B3B3660BFAULL;
            aOrbiterD = RotL64((aOrbiterD * 0x9AE3C4CFD35D3A9DULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x55202D6A68869620ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x70158AAE8E80F135ULL;
