            aOrbiterH = RotL64((aOrbiterH * 0x910653B195A22CC3ULL), 29U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x5F2B447D17B7B6AFULL) + aKeySpawnOrbiterUpdateSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x8DE5086F44BEFD8FULL) ^ aKeySpawnOrbiterUpdateSaltC[((aIndex + 4U)) & S_SALT1];
