            //
            aWandererG = aWandererG + ((((RotL64(aCross, 23U) + RotL64(aOrbiterB, 39U)) + aOrbiterF) + RotL64(aCarry, 43U)) + aKeySpawnWandererUpdateSaltB[(((31U - aIndex) + 18U)) & S_SALT1]);
