            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xBB5BC38B141CD37BULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x963E5CA364B9B8A0ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x3622448B438A6545ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0xBAA525C364570F25ULL) + aKeySpawnOrbiterUpdateSaltC[((aIndex + 23U)) & S_SALT1];
